def measure_existing_files(apps, schema_editor):
    """Fill in the byte counts for photos stored before storage limits existed."""
    Photo = apps.get_model("gallery", "Photo")

    def size(name):
        path = os.path.join(settings.MEDIA_ROOT, name) if name else ""
        return os.path.getsize(path) if path and os.path.isfile(path) else 0

    for photo in Photo.objects.all().iterator():
        photo.original_bytes = 0 if photo.drive_file_id else size(photo.image.name)
        photo.thumb_bytes = size(photo.thumbnail.name)
        photo.save(update_fields=["original_bytes", "thumb_bytes"])


